#!/usr/bin/env python3
"""Remove JavaScript and other active XSS content from an HTML file in place."""
import html
import re
import sys
from html.parser import HTMLParser
from pathlib import Path

DROP_CONTENT = {
    "script", "iframe", "frame", "frameset", "object", "embed", "applet",
    "portal",
}
DROP_ELEMENTS = {"base", "meta", "svg:script", "math:script"}
SVG_ACTIVE = {"animate", "animatemotion", "animatetransform", "set"}
URL_ATTRS = {
    "href", "src", "action", "formaction", "poster", "background", "cite",
    "data", "codebase", "classid", "archive", "profile", "usemap", "longdesc",
    "manifest", "icon", "ping", "xmlns", "xlink:href",
}
ATTR_RE = re.compile(
    r'''(?P<lead>\s+)(?P<name>[^\s=/>]+)(?P<between>\s*)'''
    r'''(?:=(?P<after>\s*)(?P<value>"[^"]*"|'[^']*'|[^\s>]*))?''', re.S
)
CTRL = re.compile(r"[\x00-\x20\x7f-\x9f\u00ad\u200b-\u200f\u2028-\u202f\u2060-\u206f\ufeff]+")
CSS_COMMENT = re.compile(r"/\*.*?\*/", re.S)
CSS_ESCAPE = re.compile(r"\\([0-9a-fA-F]{1,6})(?:\s)?|\\(.)", re.S)
CSS_BAD = re.compile(
    r"(?is)(?:expression\s*\(|(?:java|vb|live)script\s*:|behavior\s*:|"
    r"-moz-binding\s*:|@import\b|url\s*\(\s*['\"]?\s*data\s*:"
    r"\s*(?:text/html|image/svg\+xml))"
)


def decode_references(value):
    for _ in range(6):
        decoded = html.unescape(value)
        if decoded == value:
            break
        value = decoded
    return value


def normalized_url(value):
    value = decode_references(value)
    value = CTRL.sub("", value).strip().lower()
    return value.replace("\\", "")


def dangerous_url(value):
    value = normalized_url(value)
    if re.match(r"^(?:javascript|vbscript|livescript|mocha):", value):
        return True
    if value.startswith("data:"):
        return not bool(re.match(
            r"^data:image/(?:png|gif|jpe?g|webp|bmp|avif)(?:[;,]|$)", value
        ))
    return False


def css_normalized(value):
    value = decode_references(value)

    def expand(match):
        if match.group(1):
            try:
                return chr(int(match.group(1), 16))
            except (ValueError, OverflowError):
                return ""
        return match.group(2) or ""

    value = CSS_ESCAPE.sub(expand, value)
    return CTRL.sub("", CSS_COMMENT.sub("", value))


def dangerous_css(value):
    return bool(CSS_BAD.search(css_normalized(value)))


def unquote(raw):
    if len(raw) >= 2 and raw[0] in "\"'" and raw[-1] == raw[0]:
        return raw[1:-1]
    return raw


class Sanitizer(HTMLParser):
    def __init__(self, source):
        super().__init__(convert_charrefs=False)
        self.source = source
        self.line_starts = [0]
        self.line_starts.extend(m.end() for m in re.finditer("\n", source))
        self.output = []
        self.dropped = []
        self.in_style = 0

    def emit(self, value):
        if not self.dropped:
            self.output.append(value)

    def raw_at_position(self, pattern, fallback):
        line, column = self.getpos()
        start = self.line_starts[line - 1] + column
        match = re.match(pattern, self.source[start:], re.S)
        return match.group(0) if match else fallback

    @staticmethod
    def tag_attributes(raw):
        opening = re.match(r"<\s*[^\s/>]+", raw, re.S)
        if not opening:
            return []
        end = raw.rfind(">")
        if end < 0:
            end = len(raw)
        elif end and raw[end - 1] == "/":
            end -= 1
        return list(ATTR_RE.finditer(raw, opening.end(), end))

    def clean_start_tag(self, raw, tag):
        attrs = self.tag_attributes(raw)
        edits = []
        seen = set()
        http_equiv = None
        content = None

        for attr in attrs:
            name = decode_references(attr.group("name")).lower()
            raw_value = attr.group("value") or ""
            value = unquote(raw_value)
            remove = False

            if name in seen:
                remove = True
            seen.add(name)

            if name == "http-equiv":
                http_equiv = normalized_url(value)
            elif name == "content":
                content = value

            if name.startswith("on") or name in {"srcdoc", "dynsrc", "lowsrc"}:
                remove = True
            elif name == "style" and dangerous_css(value):
                remove = True
            elif name in URL_ATTRS and dangerous_url(value):
                remove = True
            elif name in {"srcset", "imagesrcset"}:
                candidates = [part.strip().split()[0]
                              for part in value.split(",") if part.strip()]
                if any(dangerous_url(candidate) for candidate in candidates):
                    remove = True
            elif name in {
                "attributename", "begin", "end", "repeatcount", "repeatdur"
            } and tag in SVG_ACTIVE:
                remove = True

            if remove:
                edits.append((attr.start(), attr.end()))

        if tag == "meta" and http_equiv in {"refresh", "set-cookie"}:
            return ""
        if tag == "meta" and content and dangerous_url(content):
            return ""

        for start, end in sorted(edits, reverse=True):
            raw = raw[:start] + raw[end:]
        return raw

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        raw = self.get_starttag_text()
        if self.dropped:
            if tag in DROP_CONTENT:
                self.dropped.append(tag)
            return
        if tag in DROP_CONTENT:
            self.dropped.append(tag)
            return
        if tag in DROP_ELEMENTS or tag in SVG_ACTIVE:
            return
        if tag == "style":
            self.in_style += 1
        self.emit(self.clean_start_tag(raw, tag))

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if self.dropped or tag in DROP_CONTENT or tag in DROP_ELEMENTS or tag in SVG_ACTIVE:
            return
        self.emit(self.clean_start_tag(self.get_starttag_text(), tag))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.dropped:
            if tag == self.dropped[-1]:
                self.dropped.pop()
            return
        if tag in DROP_CONTENT or tag in DROP_ELEMENTS or tag in SVG_ACTIVE:
            return
        if tag == "style" and self.in_style:
            self.in_style -= 1
        raw = self.raw_at_position(r"</\s*[^>]*>", "</" + tag + ">")
        self.emit(raw)

    def handle_data(self, data):
        if self.dropped:
            return
        if self.in_style and dangerous_css(data):
            return
        self.emit(data)

    def handle_entityref(self, name):
        self.emit("&" + name + ";")

    def handle_charref(self, name):
        self.emit("&#" + name + ";")

    def handle_comment(self, data):
        if not re.match(r"(?is)^\s*\[if\b", data):
            self.emit("<!--" + data + "-->")

    def handle_decl(self, declaration):
        self.emit("<!" + declaration + ">")

    def handle_pi(self, data):
        self.emit("<?" + data + ">")

    def unknown_decl(self, data):
        self.emit("<![" + data + "]>")


def sanitize(source):
    parser = Sanitizer(source)
    parser.feed(source)
    parser.close()
    return "".join(parser.output)


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: filter.py HTML_FILE")
    path = Path(sys.argv[1])
    source = path.read_text(encoding="utf-8", errors="surrogateescape")
    path.write_text(sanitize(source), encoding="utf-8", errors="surrogateescape")


if __name__ == "__main__":
    main()
