import sys
sys.path.insert(0, '/app')
from filter import sanitize

benign = '''<!DOCTYPE HTML>\n<HTML lang="en"><Head><TITLE data-x='1'>Test</TITLE></Head>\n<body><noscript><p>Notice</p></noscript><table class = "x"><tr><td title="a &amp; b">B</td></tr></table></body></HTML>\n'''
assert sanitize(benign) == benign
cases = {
    '<script>alert(1)</script><p>x</p>': '<p>x</p>',
    '<A OnClick = "x" HREF="j&#97;vascript:alert(1)" title=x>ok</A>': '<A title=x>ok</A>',
    '<img src=x onerror=x alt=y>': '<img src=x alt=y>',
    '<iframe><p>hidden</p></iframe><b>shown</b>': '<b>shown</b>',
    '<p style="width:ex\\70 ression(x)" class=x>x</p>': '<p class=x>x</p>',
    '<img srcset="ok.png 1x, javascript:x 2x" alt=x>': '<img alt=x>',
    '<meta content="0;url=javascript:x" http-equiv="refresh"><p>x</p>': '<p>x</p>',
    '<svg><animate attributeName="href"/><a href="javascript:x">x</a></svg>': '<svg><a>x</a></svg>',
}
for source, expected in cases.items():
    result = sanitize(source)
    assert result == expected, (source, result, expected)
    assert sanitize(result) == result
print('all tests passed')
