"""Tensor-parallel linear layers implemented with PyTorch distributed collectives."""

import torch
import torch.distributed as dist
import torch.nn.functional as F
from torch import nn


class _GatherLastDimension(torch.autograd.Function):
    """Gather shards in forward and select the local gradient shard in backward."""

    @staticmethod
    def forward(ctx, tensor):
        world_size = dist.get_world_size()
        rank = dist.get_rank()
        ctx.world_size = world_size
        ctx.rank = rank

        if world_size == 1:
            return tensor

        gathered = [torch.empty_like(tensor) for _ in range(world_size)]
        dist.all_gather(gathered, tensor)
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        # Every rank has the gathered output. Its local parameters only need
        # the gradient corresponding to that rank's output shard.
        return torch.chunk(grad_output, ctx.world_size, dim=-1)[ctx.rank].contiguous()


class _ReduceSum(torch.autograd.Function):
    """Sum partial outputs in forward and pass gradients through in backward."""

    @staticmethod
    def forward(ctx, tensor):
        if dist.get_world_size() == 1:
            return tensor
        result = tensor.clone()
        dist.all_reduce(result, op=dist.ReduceOp.SUM)
        return result

    @staticmethod
    def backward(ctx, grad_output):
        # The forward sum has derivative one with respect to every partial
        # result. No further reduction is needed here.
        return grad_output


class ColumnParallelLinear(nn.Module):
    """Linear layer sharded across its output features.

    Each rank stores ``out_features / world_size`` rows of the PyTorch weight
    matrix. Local results are gathered so every rank receives the complete
    output tensor.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = int(in_features)
        self.out_features = int(out_features)
        self.world_size = dist.get_world_size()
        self.rank = dist.get_rank()

        if self.out_features % self.world_size != 0:
            raise ValueError("out_features must be divisible by world_size")
        if tuple(master_weight.shape) != (self.out_features, self.in_features):
            raise ValueError(
                "master_weight must have shape "
                f"({self.out_features}, {self.in_features}), got {tuple(master_weight.shape)}"
            )

        self.output_size_per_partition = self.out_features // self.world_size
        weight_shard = torch.chunk(
            master_weight.detach(), self.world_size, dim=0
        )[self.rank].contiguous().clone()
        self.weight = nn.Parameter(weight_shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input):
        local_output = F.linear(input, self.weight, self.bias)
        return _GatherLastDimension.apply(local_output)


class RowParallelLinear(nn.Module):
    """Linear layer sharded across its input features.

    Forward expects an already-scattered input shard on each rank. Partial
    outputs are summed across ranks, and an optional full bias is added after
    that sum.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = int(in_features)
        self.out_features = int(out_features)
        self.world_size = dist.get_world_size()
        self.rank = dist.get_rank()

        if self.in_features % self.world_size != 0:
            raise ValueError("in_features must be divisible by world_size")
        if tuple(master_weight.shape) != (self.out_features, self.in_features):
            raise ValueError(
                "master_weight must have shape "
                f"({self.out_features}, {self.in_features}), got {tuple(master_weight.shape)}"
            )

        self.input_size_per_partition = self.in_features // self.world_size
        weight_shard = torch.chunk(
            master_weight.detach(), self.world_size, dim=1
        )[self.rank].contiguous().clone()
        self.weight = nn.Parameter(weight_shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, input):
        partial_output = F.linear(input, self.weight, None)
        output = _ReduceSum.apply(partial_output)
        if self.bias is not None:
            output = output + self.bias
        return output
